```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "audifonos cancelacion ruido",
        "category": "audifonos",
        "max_price": 170000,
        "attributes": {
          "cancelacion_ruido": true
        }
      }
    },
    {
      "id": "s2",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.0.id",
        "limit": 3
      }
    },
    {
      "id": "s3",
      "op": "get_product",
      "args": {
        "id": "$s1.1.id"
      }
    },
    {
      "id": "s4",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.1.id",
        "limit": 3
      }
    },
    {
      "id": "s5",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id"]
      }
    },
    {
      "id": "s6",
      "op": "respond",
      "plantilla": "Encontré {cantidad} opciones de audifonos con cancelación de ruido dentro de tu presupuesto. Te recomiendo estos dos:\n\n1. {nombre1} <<rec:{id1}>> - ${precio1} CLP. Evaluación: {rating1}/5. {resumen1}\n\n2. {nombre2} <<rec:{id2}>> - ${precio2} CLP. Evaluación: {rating2}/5. {resumen2}\n\n<<cmp:{id1},{id2}>> El más económico es {mas_barato}, y el mejor evaluado es {mejor_evaluado}.",
      "vars": {
        "cantidad": "$s1.length",
        "nombre1": "$s1.0.name",
        "id1": "$s1.0.id",
        "precio1": "$s1.0.price_clp",
        "rating1": "$s1.0.avg_rating",
        "resumen1": "$s2",
        "nombre2": "$s3.name",
        "id2": "$s3.id",
        "precio2": "$s3.price_clp",
        "rating2": "$s3.avg_rating",
        "resumen2": "$s4",
        "mas_barato": "$s5.mas_barato",
        "mejor_evaluado": "$s5.mejor_evaluado"
      }
    }
  ]
}
